root=pathlib.Path('curriculum-catalogue/senior');root.mkdir(parents=True,exist_ok=True);documents=[];content={}
for filename,subject,area,years,kind in rows:
 source=directory/filename;raw=source.read_bytes();text=subprocess.check_output(['pdftotext','-layout',str(source),'-']).decode();pages=text.split('\f');
 if not pages[-1].strip():pages.pop()
 if any(not page.strip() for page in pages):raise ValueError('Empty extraction page: '+filename)
 slug=unicodedata.normalize('NFKD',source.stem).encode('ascii','ignore').decode().lower();id='senior-'+re.sub('[^a-z0-9]+','-',slug).strip('-')
 status='Consultation draft, 1st–29th October 2026' if kind=='consultation-draft' else 'Supporting document; not a teaching sequence' if kind=='supporting-document' else 'Supporting information sheet; not a teaching sequence' if kind=='infosheet' else 'October 2026 teaching content; proposed curriculum statement; progress and assessment information in development'
 d={'id':id,'subject':subject,'learningArea':area,'years':years,'yearRange':('Year '+str(years[0])) if len(years)==1 else 'Years '+str(years[0])+'–'+str(years[-1]),'kind':kind,'version':'October 2026','publicationStatus':status,'sourceFilename':filename,'acquisition':'Ministry PDF supplied by the user','pageCount':len(pages),'sha256Original':hashlib.sha256(raw).hexdigest(),'attribution':'Ministry of Education, Crown copyright','licenceUrl':'https://newzealandcurriculum.tahurangi.education.govt.nz/copyright','availableForJuniorStatements':False,'availableForProgression':kind=='curriculum','checkedOn':'2026-10-30','contentPath':id+'.json'}
 body={'format':'PDF page text with column spacing retained','scope':'Senior reference only. Never use as Years 7–10 curriculum statements or mandatory junior assessment requirements.','pages':[{'page':i+1,'text':s.rstrip()} for i,s in enumerate(pages)]};documents.append(d);content[id]=body;(root/(id+'.json')).write_text(json.dumps(body,ensure_ascii=False,indent=2)+'\n')
index={'version':'2026-10-30-senior-1','scope':'Supplied senior curriculum references and information sheets; not a complete senior curriculum collection.','documents':documents,'complete':False};(root/'index.json').write_text(json.dumps(index,ensure_ascii=False,indent=2)+'\n')
(root/'README.md').write_text('# Senior curriculum references\n\n60 user-supplied Ministry PDFs, October 2026, extracted as page-numbered text. Original filenames, hashes, page counts, subject ranges and status are retained. The catalogue is a supplied subset, not all senior subjects.\n\nFifty teaching-content documents are proposed curriculum statements, eight are supporting infosheets, one is a supporting document, and Outdoor Education is explicitly a consultation draft. No source is presented as a junior curriculum requirement or a final assessment specification. The junior planner may receive relevant senior teaching-content references only for connections to future learning; infosheets, supporting documents and consultation drafts are excluded from automatic progression retrieval.\n\nFull PDF originals, images and logos are not included in the website; only attributed text derivatives are stored. Originals remain unchanged.\n')
encoded={id:base64.b64encode(gzip.compress(json.dumps(body,ensure_ascii=False).encode(),mtime=0)).decode() for id,body in content.items()}
pathlib.Path('worker/senior-catalogue-data.js').write_text('// Generated by scripts/add-senior-catalogue.py. Attributed text derivatives only.\nexport const seniorCatalogue = '+json.dumps(index,ensure_ascii=False)+';\nconst seniorEncoded = '+json.dumps(encoded)+';\nexport async function readSeniorSource(id){const data=seniorEncoded[id];if(!data)throw Error("Senior source not found");const bytes=Uint8Array.from(atob(data),c=>c.charCodeAt(0));return new Response(new Blob([bytes]).stream().pipeThrough(new DecompressionStream("gzip"))).json();}\n')
print(json.dumps({'documents':len(documents),'pages':sum(d['pageCount'] for d in documents),'teachingDocuments':sum(d['kind']=='curriculum' for d in documents),'infosheets':sum(d['kind']=='infosheet' for d in documents),'supportingDocuments':sum(d['kind']=='supporting-document' for d in documents),'consultationDrafts':sum(d['kind']=='consultation-draft' for d in documents),'characters':sum(sum(len(p['text']) for p in b['pages']) for b in content.values())}))
